// === ESTRUCTURA DEL PATRÓN ADAPTER ===

// 1. Interfaz Objetivo (lo que el cliente espera)
interface PaymentProvider {
  pay(amount: number, currency: string): Promise<PaymentResult>;
  refund(transactionId: string): Promise<boolean>;
}

// 2. Adaptados (clases existentes con interfaces incompatibles)
class StripeAPI {
  charge(params: { amount_in_cents: number; currency_code: string }) {
    return { id: 'stripe_tx_123', status: 'succeeded' };
  }
  createRefund(charge_id: string) {
    return { refunded: true };
  }
}

class PayPalAPI {
  processPayment(value: number, coin: string) {
    return { confirmation: 'pp_tx_456', state: 'completed' };
  }
  returnPayment(confirmation: string) {
    return { returned: true };
  }
}

// 3. Adaptadores (traducen la interfaz)
class StripeAdapter implements PaymentProvider {
  private stripe = new StripeAPI();

  async pay(amount: number, currency: string): Promise<PaymentResult> {
    const result = this.stripe.charge({
      amount_in_cents: amount * 100,
      currency_code: currency
    });
    return { success: true, transactionId: result.id };
  }

  async refund(transactionId: string): Promise<boolean> {
    const result = this.stripe.createRefund(transactionId);
    return result.refunded;
  }
}

class PayPalAdapter implements PaymentProvider {
  private paypal = new PayPalAPI();

  async pay(amount: number, currency: string): Promise<PaymentResult> {
    const result = this.paypal.processPayment(amount, currency);
    return { success: true, transactionId: result.confirmation };
  }

  async refund(transactionId: string): Promise<boolean> {
    const result = this.paypal.returnPayment(transactionId);
    return result.returned;
  }
}

// 4. Cliente — solo conoce la interfaz PaymentProvider
async function processCheckout(provider: PaymentProvider, amount: number) {
  const result = await provider.pay(amount, 'USD');
  console.log(`Pago procesado: ${result.transactionId}`);
}

