// Interfaz común — todos los proveedores hablan el mismo idioma
interface PaymentProvider {
  pay(amount: number, currency: string): Promise<PaymentResult>;
  refund(transactionId: string): Promise<boolean>;
}

// Adaptadores — traducen al SDK específico de cada proveedor
class StripeAdapter implements PaymentProvider {
  async pay(amount: number, currency: string) {
    const result = await stripe.charge({ amount_in_cents: amount * 100, currency_code: currency });
    return { success: true, transactionId: result.id };
  }
  async refund(txId: string) { return stripe.createRefund(txId).refunded; }
}

// El cliente solo usa la interfaz — cambiar proveedor es trivial
async function checkout(provider: PaymentProvider, amount: number) {
  return provider.pay(amount, 'USD');
}

